mapper.select:
SELECT s.vendor_id, SUM(s.amount) AS original_amount, SUM(s.pg_fee_amount) AS pg_fee_amount, SUM(s.platform_fee_amount) AS platform_fee_amount, SUM(s.net_amount) AS final_amount, COUNT(*) AS settlement_count FROM settlement s JOIN payment p ON p.id = s.payment_id WHERE s.status = 'PENDING' AND s.is_deleted = false AND p.is_deleted = false AND s.vendor_id > #{lastId}
AND s.created_at >= #{startDate}
AND s.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
GROUP BY s.vendor_id ORDER BY s.vendor_id ASC LIMIT #{limit}

